import numpy as np
lines=open('opt_free.xyz').read().splitlines(); n=int(lines[0])
syms=[l.split()[0] for l in lines[2:2+n]]
pos=np.array([[float(x) for x in l.split()[1:4]] for l in lines[2:2+n]])
cov={'H':0.31,'C':0.76,'N':0.71,'Si':1.11,'Au':1.36}
bonds={}
for i in range(n):
    bonds[i]=[]
for i in range(n):
    for j in range(i+1,n):
        d=np.linalg.norm(pos[i]-pos[j])
        if d < cov[syms[i]]+cov[syms[j]]+0.45:
            bonds[i].append(j); bonds[j].append(i)
print('Au neighbors:', bonds[0], [syms[k] for k in bonds[0]])
for si in (1,32):
    print('Si',si,'neighbors:', [(k,syms[k]) for k in bonds[si]])
for i,s in enumerate(syms):
    if s=='N':
        print('N',i,'neighbors:', [(k,syms[k]) for k in bonds[i]])
# check methyl carbons (C with 3 H + 1 C)
me=[i for i,s in enumerate(syms) if s=='C' and sum(1 for k in bonds[i] if syms[k]=='H')==3]
print('methyl C:', me)
for m in me:
    print('  methyl', m, 'attached to', [(k,syms[k]) for k in bonds[m] if k!=m and syms[k]!='H'])
# aromatic C counts per indole: each indole = 9 C
